          efeitos: [{ v: 'global.cooperacao', d: 1 }, { v: 'global.tensao', d: -1 }, { v: 'apoio', d: -1 }],
          porque: 'Os ataques no mar nascem da guerra em terra: tratar a causa é mais lento, mas é o que reabre a rota de vez.',
